    } else {
        cmp::min(to as usize, len)
    };
    let n = to - from;
    let self_buffer = buffer_new_with_size(n)?;
    unsafe {
        ptr::copy_nonoverlapping(buf.data.add(from), self_buffer.data, n);
    }
    Some(self_buffer)
}

unsafe fn strlen(data: *mut i8) -> usize {
